import type { MetadataRoute } from "next";

/**
 * PWA manifest (CRM Phase 2). Served by Next at /manifest.webmanifest.
 * Icons are generated by the /icon-* routes (logo over the night-sky
 * photo); the app installs as "Canny Capital Portal", standalone.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Canny Capital Portal",
    short_name: "Canny Capital Portal",
    description:
      "Canny Capital Partners — Arizona acquisition pipeline, executive sourcing, and market intel.",
    start_url: "/overview",
    display: "standalone",
    orientation: "any",
    theme_color: "#0d1f3c",
    background_color: "#0d1f3c",
    icons: [
      { src: "/icon-192-v2", sizes: "192x192", type: "image/png" },
      { src: "/icon-512-v2", sizes: "512x512", type: "image/png" },
      {
        src: "/icon-maskable-v2",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
